import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import { Polymorphic } from "@kobalte/core/polymorphic";

import { cn } from "~/lib/utils.ts";
import type { ButtonProps } from "./button.tsx";
import { Button } from "./button.tsx";
import type { VariantProps } from "class-variance-authority";
import { cva } from "class-variance-authority";
import type { Component, ComponentProps, ValidComponent } from "solid-js";

import { splitProps } from "solid-js";

const attachmentVariants = cva(
  "rounded-lg w-fit focus-within:ring-1 focus-within:ring-ring/30 group/attachment relative flex max-w-full min-w-0 shrink-0 flex-wrap border bg-card text-card-foreground transition-colors has-[>a,>button]:hover:bg-muted/50 data-[state=error]:border-destructive/30 data-[state=idle]:border-dashed",
  {
    variants: {
      size: {
        default: "gap-2 has-data-[slot=attachment-content]:px-2 has-data-[slot=attachment-content]:py-1.5 has-data-[slot=attachment-media]:p-1.5 text-xs",
        sm: "gap-2.5 has-data-[slot=attachment-content]:px-1.5 has-data-[slot=attachment-content]:py-1 has-data-[slot=attachment-media]:p-1 text-xs",
        xs: "gap-1.5 has-data-[slot=attachment-content]:px-1.5 has-data-[slot=attachment-content]:py-1 has-data-[slot=attachment-media]:p-1 text-xs rounded-md",
      },
      orientation: {
        horizontal: "min-w-40 items-center",
        vertical: "w-24 has-data-[slot=attachment-content]:w-30 flex-col",
      },
    },
    defaultVariants: {
      size: "default",
      orientation: "horizontal",
    },
  },
);

type AttachmentProps =
  & ComponentProps<"div">
  & VariantProps<typeof attachmentVariants>
  & {
    state?: "idle" | "uploading" | "processing" | "error" | "done";
  };

const Attachment: Component<AttachmentProps> = (props) => {
  const [local, others] = splitProps(props, [
    "class",
    "state",
    "size",
    "orientation",
  ]);
  return (
    <div
      data-slot="attachment"
      data-state={local.state ?? "done"}
      data-size={local.size ?? "default"}
      data-orientation={local.orientation ?? "horizontal"}
      class={cn(
        attachmentVariants({
          size: local.size,
          orientation: local.orientation,
        }),
        local.class,
      )}
      {...others}
    />
  );
};

const attachmentMediaVariants = cva(
  "bg-muted text-foreground w-10 rounded-md group-data-[size=sm]/attachment:w-8 group-data-[size=xs]/attachment:w-7 group-data-[size=xs]/attachment:rounded-sm [&_svg:not([class*='size-'])]:size-4 group-data-[size=xs]/attachment:[&_svg:not([class*='size-'])]:size-3.5 group-data-[orientation=vertical]/attachment:w-full group-data-[orientation=vertical]/attachment:[&_svg:not([class*='size-'])]:size-6 group-data-[orientation=vertical]/attachment:*:data-[slot=spinner]:size-6! relative flex aspect-square shrink-0 items-center justify-center overflow-hidden group-data-[state=error]/attachment:bg-destructive/10 group-data-[state=error]/attachment:text-destructive [&_svg]:pointer-events-none",
  {
    variants: {
      variant: {
        icon: "",
        image:
          "opacity-60 group-data-[state=idle]/attachment:opacity-100 group-data-[state=done]/attachment:opacity-100 *:[img]:aspect-square *:[img]:w-full *:[img]:object-cover",
      },
    },
    defaultVariants: {
      variant: "icon",
    },
  },
);

type AttachmentMediaProps =
  & ComponentProps<"div">
  & VariantProps<typeof attachmentMediaVariants>;

const AttachmentMedia: Component<AttachmentMediaProps> = (props) => {
  const [local, others] = splitProps(props, ["class", "variant"]);
  return (
    <div
      data-slot="attachment-media"
      data-variant={local.variant ?? "icon"}
      class={cn(
        attachmentMediaVariants({ variant: local.variant }),
        local.class,
      )}
      {...others}
    />
  );
};

const AttachmentContent: Component<ComponentProps<"div">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <div
      data-slot="attachment-content"
      class={cn("leading-tight group-data-[orientation=vertical]/attachment:px-1 max-w-full min-w-0 flex-1", local.class)}
      {...others}
    />
  );
};

const AttachmentTitle: Component<ComponentProps<"span">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <span
      data-slot="attachment-title"
      class={cn(
        "font-medium block max-w-full min-w-0 truncate group-data-[state=processing]/attachment:shimmer group-data-[state=uploading]/attachment:shimmer",
        local.class,
      )}
      {...others}
    />
  );
};

const AttachmentDescription: Component<ComponentProps<"span">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <span
      data-slot="attachment-description"
      class={cn(
        "mt-0.5 text-xs block min-w-0 truncate text-muted-foreground group-data-[state=error]/attachment:text-destructive/80",
        "max-w-full",
        local.class,
      )}
      {...others}
    />
  );
};

const AttachmentActions: Component<ComponentProps<"div">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <div
      data-slot="attachment-actions"
      class={cn(
        "group-data-[orientation=vertical]/attachment:absolute group-data-[orientation=vertical]/attachment:top-3 group-data-[orientation=vertical]/attachment:right-3 relative z-20 group-data-[orientation=vertical]/attachment:gap-1 flex shrink-0 items-center",
        local.class,
      )}
      {...others}
    />
  );
};

const AttachmentAction = <T extends ValidComponent = "button">(
  props: PolymorphicProps<T, ButtonProps<T>>,
) => {
  const [local, others] = splitProps(props as ButtonProps, [
    "class",
    "variant",
    "size",
  ]);
  return (
    <Button
      data-slot="attachment-action"
      variant={local.variant ?? "ghost"}
      size={local.size ?? "icon-xs"}
      class={cn(local.class)}
      {...others}
    />
  );
};

type AttachmentTriggerProps =
  & ComponentProps<"button">
  & { class?: string | undefined };

const AttachmentTrigger = <T extends ValidComponent = "button">(
  props: PolymorphicProps<T, AttachmentTriggerProps>,
) => {
  const [local, others] = splitProps(props as AttachmentTriggerProps, [
    "class",
    "type",
  ]);
  return (
    <Polymorphic
      as="button"
      data-slot="attachment-trigger"
      // Default the button type, but never stamp `type` onto a polymorphic
      // element that has no such attribute (an anchor, say). Upstream makes
      // the same distinction with `asChild`.
      type={(props.as ?? "button") === "button"
        ? local.type ?? "button"
        : local.type}
      class={cn(
        "absolute inset-0 z-10 outline-none",
        local.class,
      )}
      {...others}
    />
  );
};

const AttachmentGroup: Component<ComponentProps<"div">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <div
      data-slot="attachment-group"
      class={cn(
        "gap-3 scroll-px-1 py-1 flex min-w-0 scroll-fade-x snap-x snap-mandatory no-scrollbar overflow-x-auto overscroll-x-contain *:data-[slot=attachment]:flex-none *:data-[slot=attachment]:snap-start",
        local.class,
      )}
      {...others}
    />
  );
};

export type { AttachmentMediaProps, AttachmentProps };
export {
  Attachment,
  AttachmentAction,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentGroup,
  AttachmentMedia,
  AttachmentTitle,
  AttachmentTrigger,
  attachmentVariants,
};
